-- Dolphin takes its colours from the wallpaper theme: this dir holds a dolphinrc that selects the "Cwal" scheme,
-- generated by cwal from ~/.config/cwal/templates/colors-kde.colors. Only set in Hyprland, so KDE keeps its own theme.
hl.env("XDG_CONFIG_DIRS", os.getenv("HOME") .. "/.config/hypr/xdg:/etc/xdg")
